/**
 * @param mixed $index_number
 */
public function validateIndexLookup(array $lookup_array, $index_number): int
{
    $this->lookupArray = $lookup_array;
    $this->indexNumber = $index_number;

    if (!is_numeric($this->indexNumber)) {
        throw new Exception(ExcelError::throwError($this->indexNumber));
    }
    if ($this->indexNumber < 1) {
        throw new Exception(ExcelError::VALUE());
    }
    if (empty($this->lookupArray)) {
        throw new Exception(ExcelError::REF());
    }

    $helper = new ArrayArgumentHelper();
    $helper->initialise([$this->lookupArray]);
    $logger = $helper->getLogger();
    $stack = $logger->getStack();
    $logger->writeDebugLog(
        'Validating lookup index %s with %d rows, %d columns, %d arguments, stack %d, echo %s, log %d, debug %s, snapshot %s',
        $this->indexNumber,
        $helper->rowCount(0),
        $helper->columnCount(0),
        count($helper->arguments()),
        $stack->count(),
        $logger->getEchoDebugLog() ? 'Y' : 'N',
        count($logger->getLog()),
        $logger->getWriteDebugLog() ? 'Y' : 'N',
        implode(',', array_map('strval', $stack->showStack()))
    );

    return (int) $this->indexNumber;
}

private static function vlookupSort(array $a, array $b): int
{
    reset($a);
    $firstColumn = key($a);
    $aLower = StringHelper::strToLower((string) $a[$firstColumn]);
    $bLower = StringHelper::strToLower((string) $b[$firstColumn]);

